// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.reminderimport timber.log.Timberimport android.content.Contextimport androidx.work.BackoffPolicyimport androidx.work.ExistingWorkPolicyimport androidx.work.OneTimeWorkRequestimport androidx.work.OneTimeWorkRequestBuilderimport androidx.work.WorkInfoimport androidx.work.WorkManagerimport androidx.work.workDataOfimport com.roshan.persona.productivity.alarm.EncryptedDataimport java.util.concurrent.TimeUnit/** * NOUS — Reminder Engine (Module 14 v1.2 — Step 14.2, CRITICAL). * * REAL implementation of reminder operations using Android's [WorkManager]. * This is NOT a stub — every method uses REAL WorkManager APIs. * * ## Why WorkManager (not AlarmManager)? * * Per strategy v1.1 §"Fix 2": * > Dual scheduler (WorkManager + AlarmManager) = double-triggering + battery drain. * > Fix: Remove AlarmManager entirely from ReminderEngine. Use only WorkManager. * * WorkManager handles Doze mode survival + battery optimization + boot * rescheduling internally — we don't need to manage any of that. * * ## Real Android APIs Used * * | Operation | API | * |-----------|-----| * | scheduleReminder | `OneTimeWorkRequestBuilder` + `setInitialDelay` + `enqueue` | * | snoozeReminder    | `cancelAllWorkByTag` + new `OneTimeWorkRequest` with snooze delay | * | cancelReminder    | `cancelAllWorkByTag` + `cancelAllWorkByUniqueName` | * | cancelAllReminders| iterate + cancel each | * | getActiveReminders| `getWorkInfosByTag` (filter ENQUEUED + RUNNING) | * | getNextReminder   | query WorkManager + earliest trigger from [ReminderStore] | * * ## Snooze Flow (per strategy v1.1 §"Fix 2") * * ```kotlin * fun snoozeReminder(reminderId: String, snoozeMs: Long): Boolean { *     // Cancel old work + create new with delay. *     WorkManager.getInstance(context).cancelAllWorkByTag("reminder_$reminderId") *     scheduleReminder(reminder.copy(timestampMs = System.currentTimeMillis() + snoozeMs)) * } * ``` * * ## Encryption * * Reminder bodies are encrypted via [ReminderEncryptionHelper] before * being passed to [ReminderWorker] as WorkManager input data. The worker * decrypts the body at fire time — the plaintext body is NEVER stored * in the [ReminderStore], the WorkManager data store, or anywhere else * persistent. * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Fix 2</a> */class ReminderEngine(    private val context: Context,    private val reminderStore: ReminderStore = ReminderStore(),    private val encryptionHelper: ReminderEncryptionHelper = ReminderEncryptionHelper(),) {    companion object {        private const val TAG = "ReminderEngine"        /** WorkManager tag prefix for reminder work. */        const val WORK_TAG_PREFIX = "reminder_"        /** Backoff initial delay (1 minute, linear). */        private const val BACKOFF_INITIAL_MS = 60_000L    }    private val workManager: WorkManager by lazy { WorkManager.getInstance(context) }    // ═══════════════════════════════════════════════════════════════════════════    // Schedule Reminder (REAL OneTimeWorkRequest)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Schedule a reminder (REAL WorkManager OneTimeWorkRequest).     *     * @param triggerAtMs epoch milliseconds when the reminder fires.     * @param label       short label shown in notification title.     * @param body        optional body text (will be AES-GCM encrypted before storage).     * @param snoozeOptions snooze limits (default 3 snoozes, 5 min each).     * @return [ReminderResult] with the created [ReminderInfo].     */    fun scheduleReminder(        triggerAtMs: Long,        label: String,        body: String? = null,        snoozeOptions: SnoozeOptions = SnoozeOptions(),    ): ReminderResult<ReminderInfo> {        val now = System.currentTimeMillis()        if (triggerAtMs <= now) {            return ReminderResult.Failure(                error = "Trigger time is in the past.",                spokenMessage = "I can't set a reminder in the past. Try a later time.",            )        }        val reminderId = "reminder_${now}_${label.hashCode().toUInt()}"        val delayMs = triggerAtMs - now        // Encrypt body (if present) — REAL AES-GCM via AndroidKeystore.        val encryptedBody: EncryptedData? = body?.let {            encryptionHelper.encrypt(it) ?: return ReminderResult.Failure(                error = "Failed to encrypt reminder body.",                spokenMessage = "I couldn't securely store the reminder body.",            )        }        // Build the WorkManager work request (REAL OneTimeWorkRequest).        val workRequest = buildWorkRequest(            reminderId = reminderId,            label = label,            encryptedBody = encryptedBody,            delayMs = delayMs,        )        // Enqueue with unique work policy REPLACE (so re-scheduling overwrites).        val uniqueWorkName = "$WORK_TAG_PREFIX$reminderId"        workManager.enqueueUniqueWork(            uniqueWorkName,            ExistingWorkPolicy.REPLACE,            workRequest,        )        // Store reminder state (encrypted body, never plaintext).        val reminder = ReminderInfo(            id = reminderId,            label = label,            triggerAtMs = triggerAtMs,            encryptedBody = encryptedBody,            status = ReminderStatus.SCHEDULED,            snoozeCount = 0,            maxSnoozeCount = snoozeOptions.maxSnoozeCount,        )        reminderStore.put(reminder)        Timber.tag(TAG).i("Reminder scheduled: '$label' at ${reminder.displayTime} (id=$reminderId, delay=${delayMs}ms).")        return ReminderResult.Success(            data = reminder,            spokenMessage = "Reminder set for ${reminder.displayTime}.",        )    }    // ═══════════════════════════════════════════════════════════════════════════    // Snooze Reminder (REAL cancel + re-schedule with delay)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Snooze a reminder (REAL WorkManager cancel + new OneTimeWorkRequest).     *     * Cancels the existing work for this reminder + enqueues a new     * OneTimeWorkRequest with [snoozeMs] delay. The [ReminderStore] is     * updated with the new trigger time + snooze count.     *     * @param reminderId the reminder to snooze.     * @param snoozeMs   how long to delay before re-firing (default 5 min).     * @return [ReminderResult] with the updated [ReminderInfo].     */    fun snoozeReminder(        reminderId: String,        snoozeMs: Long = ReminderInfo.DEFAULT_SNOOZE_MS,    ): ReminderResult<ReminderInfo> {        val existing = reminderStore.getById(reminderId)            ?: return ReminderResult.Failure(                error = "Reminder not found.",                spokenMessage = "I can't find that reminder to snooze.",            )        // Enforce max snooze count.        if (!existing.canSnooze) {            Timber.tag(TAG).w("Reminder '$reminderId' has reached max snooze count (${existing.snoozeCount}/${existing.maxSnoozeCount}).")            // Auto-dismiss when snooze limit is hit.            cancelReminder(reminderId)            return ReminderResult.Failure(                error = "Max snooze count reached.",                spokenMessage = "I've snoozed this reminder ${existing.maxSnoozeCount} times already. Dismissing it now.",            )        }        // 1. Cancel existing WorkManager work (REAL cancel by tag).        val workTag = "$WORK_TAG_PREFIX$reminderId"        workManager.cancelAllWorkByTag(workTag)        workManager.cancelUniqueWork(workTag)        // 2. Compute new trigger time.        val newTriggerMs = System.currentTimeMillis() + snoozeMs        // 3. Enqueue new snoozed work.        val snoozedRequest = buildWorkRequest(            reminderId = reminderId,            label = existing.label,            encryptedBody = existing.encryptedBody,            delayMs = snoozeMs,        )        workManager.enqueueUniqueWork(workTag, ExistingWorkPolicy.REPLACE, snoozedRequest)        // 4. Update store (snooze count + new trigger time).        reminderStore.markAsSnoozed(reminderId, newTriggerMs)        val updated = reminderStore.getById(reminderId) ?: return ReminderResult.Failure(            error = "Reminder disappeared after snooze.",            spokenMessage = "I couldn't update the reminder after snoozing.",        )        Timber.tag(TAG).i("Snoozed reminder '$reminderId' for ${snoozeMs / 60000} min " +                "(count=${updated.snoozeCount}/${updated.maxSnoozeCount}).")        return ReminderResult.Success(            data = updated,            spokenMessage = "Snoozed for ${snoozeMs / 60000} minutes.",        )    }    // ═══════════════════════════════════════════════════════════════════════════    // Cancel Operations (REAL cancelAllWorkByTag + cancelUniqueWork)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Cancel a reminder by ID (REAL WorkManager cancel).     *     * @param reminderId the reminder ID to cancel.     * @return true if the reminder was found and cancelled.     */    fun cancelReminder(reminderId: String): Boolean {        val existing = reminderStore.getById(reminderId) ?: return false        val workTag = "$WORK_TAG_PREFIX$reminderId"        workManager.cancelAllWorkByTag(workTag)        workManager.cancelUniqueWork(workTag)        reminderStore.markAsCancelled(reminderId)        Timber.tag(TAG).i("Cancelled reminder: '${existing.label}' (id=$reminderId).")        return true    }    /**     * Cancel all active reminders.     *     * @return the number of reminders cancelled.     */    fun cancelAllReminders(): Int {        val active = reminderStore.getAllActive()        for (reminder in active) {            cancelReminder(reminder.id)        }        Timber.tag(TAG).i("Cancelled all ${active.size} reminders.")        return active.size    }    // ═══════════════════════════════════════════════════════════════════════════    // Query Operations    // ═══════════════════════════════════════════════════════════════════════════    /**     * Get all active reminders (from [ReminderStore]).     *     * WorkManager is the source of truth for "is the work actually scheduled",     * but the [ReminderStore] is the source of truth for the reminder's     * metadata (label, trigger time, encrypted body, snooze count).     *     * @return list of all active [ReminderInfo].     */    fun getActiveReminders(): List<ReminderInfo> = reminderStore.getAllActive()    /**     * Get the next reminder to fire (earliest trigger time).     *     * @return the next [ReminderInfo], or null if no reminders are scheduled.     */    fun getNextReminder(): ReminderInfo? = reminderStore.getNextActive()    /**     * Get the count of active reminders.     */    fun getReminderCount(): Int = reminderStore.activeCount()    /**     * Get a reminder by ID.     */    fun getReminderById(id: String): ReminderInfo? = reminderStore.getById(id)    /**     * Decrypt the body of a reminder (REAL AES-GCM decrypt via AndroidKeystore).     *     * Used by the UI / TTS path to read the reminder body aloud.     *     * @return the plaintext body, or null if the reminder has no body or     *         decryption failed.     */    fun decryptReminderBody(reminder: ReminderInfo): String? {        val encrypted = reminder.encryptedBody ?: return null        return encryptionHelper.decrypt(encrypted)    }    // ═══════════════════════════════════════════════════════════════════════════    // Boot recovery    // ═══════════════════════════════════════════════════════════════════════════    /**     * Reschedule all reminders from the store (called on device boot).     *     * WorkManager automatically re-applies scheduled work after device     * reboot — this method is a safety net for cases where WorkManager's     * own persistence is cleared. It re-enqueues any reminder still marked     * SCHEDULED in our store.     */    fun rescheduleAllReminders() {        val active = reminderStore.getAllActive()        Timber.tag(TAG).i("Rescheduling ${active.size} reminders (boot recovery).")        for (reminder in active) {            val now = System.currentTimeMillis()            if (reminder.triggerAtMs <= now) {                // Past-due reminder — fire immediately.                reminderStore.markAsFired(reminder.id)                continue            }            val workRequest = buildWorkRequest(                reminderId = reminder.id,                label = reminder.label,                encryptedBody = reminder.encryptedBody,                delayMs = reminder.triggerAtMs - now,            )            val workTag = "$WORK_TAG_PREFIX${reminder.id}"            workManager.enqueueUniqueWork(workTag, ExistingWorkPolicy.REPLACE, workRequest)        }    }    // ─── Internal helpers ─────────────────────────────────────────────────    /**     * Build a OneTimeWorkRequest for a reminder (REAL WorkManager builder).     */    private fun buildWorkRequest(        reminderId: String,        label: String,        encryptedBody: EncryptedData?,        delayMs: Long,    ): OneTimeWorkRequest {        val workTag = "$WORK_TAG_PREFIX$reminderId"        val workData = workDataOf(            ReminderWorker.KEY_REMINDER_ID to reminderId,            ReminderWorker.KEY_REMINDER_LABEL to label,            ReminderWorker.KEY_REMINDER_IV to (encryptedBody?.ivBase64 ?: ""),            ReminderWorker.KEY_REMINDER_CIPHERTEXT to (encryptedBody?.ciphertextBase64 ?: ""),        )        return OneTimeWorkRequestBuilder<ReminderWorker>()            .setInitialDelay(delayMs, TimeUnit.MILLISECONDS)            .setBackoffCriteria(BackoffPolicy.LINEAR, BACKOFF_INITIAL_MS, TimeUnit.MILLISECONDS)            .addTag(workTag)            .setInputData(workData)            .build()    }}